"""Add the MLFlowPro Sphinx handbook and a documentation build check."""

import ast
from datetime import datetime
from pathlib import Path

FILES = {'docs/README.md': "# MLFlowPro documentation\n\nThis handbook covers installation, architecture, tracked training, Bayesian\nhyperparameter tuning, the API, evaluation, deployment, and current limitations.\nThe source files are in `docs/source/`. Sphinx turns them into searchable HTML.\n\nFrom the repository root in your activated environment:\n\n```powershell\npython -m pip install -r requirements-docs.txt\npython -m sphinx -n -W --keep-going -b html docs/source docs/build/html\nStart-Process .\\docs\\build\\html\\index.html\n```\n\nThe build should finish with **build succeeded**. The `-W` option makes a\ndocumentation warning fail the build; `-n` checks missing cross-references.\nThis also runs in `.github/workflows/documentation.yml` on relevant pushes and\npull requests. Generated `docs/build/` files are ignored; commit the sources.\n\nSphinx is pinned to 8.2.3 to support the project's Python 3.11 environment.\nBuilding the handbook does not start Django, read `.env`, or require API keys.\n\n## Pages\n\n- [Installation and local setup](source/setup.rst)\n- [Architecture and concepts](source/architecture.rst)\n- [Training, tuning, and versioning](source/experiments.rst)\n- [API reference](source/api.rst)\n- [Models, evaluation, and results](source/evaluation.rst)\n- [Deployment, testing, and project scope](source/deployment.rst)\n\n## Keep the documentation accurate\n\nUpdate these pages when routes, settings, measurements, or deployment behavior\nchange. Keep the repository README and presentation consistent with the actual\nimplementation. The October 19 tuned run measured 91.06% test accuracy and\n91.05% test macro F1; suggestions from an LLM are not measured experiments.\n", 'docs/source/api.rst': 'API reference\n=============\n\nAll paths below are relative to the Django application\'s origin. The dashboard\nuses same-origin requests locally and on Render.\n\nPrediction\n----------\n\n``POST /api/predict/`` accepts a JSON object:\n\n.. code-block:: json\n\n   {"review": "The movie was excellent.", "version_id": null}\n\n``review`` must be a nonblank string of at most 10,000 characters. Omit\n``version_id`` or send null to use the original Logistic Regression model.\nSend a registered model-version UUID to select that pipeline.\n\nA successful response contains:\n\n.. list-table::\n   :header-rows: 1\n\n   * - Field\n     - Meaning\n   * - ``prediction``\n     - ``Positive`` or ``Negative``.\n   * - ``confidence``\n     - Largest predicted class probability, between zero and one.\n   * - ``model_name``\n     - Classifier identifier used for inference.\n   * - ``version_id``\n     - Selected UUID, or null for the original default model.\n\nHTTP 400 indicates invalid input, 404 indicates an unknown version, and 503\nindicates an unavailable or incompatible model file. The endpoint is public.\nWhen using a logged-in Django session, include ``X-CSRFToken`` on the POST.\n\nPowerShell example using an anonymous request:\n\n.. code-block:: powershell\n\n   $body = @{ review = "This was an excellent movie with great acting." } | ConvertTo-Json\n   Invoke-RestMethod -Uri "http://127.0.0.1:8000/api/predict/" -Method Post -ContentType "application/json" -Body $body\n\nExperiment and version endpoints\n--------------------------------\n\n.. list-table::\n   :header-rows: 1\n   :widths: 38 22 40\n\n   * - Endpoint\n     - Methods\n     - Access\n   * - ``/api/model-versions/``\n     - GET\n     - Public read-only version registry.\n   * - ``/api/model-versions/<uuid>/``\n     - GET\n     - Public read-only version details.\n   * - ``/api/experiment-results/``\n     - GET; authenticated writes\n     - Public metrics; writes require authentication.\n   * - ``/api/experiments/``\n     - GET, POST\n     - Authentication required.\n   * - ``/api/model-settings/``\n     - GET, POST\n     - Authentication required.\n\nThe experiment, settings, and result viewsets also expose detail URLs with\nGET, PUT, PATCH, and DELETE subject to their permission policy. The registry\nexposes metadata and provenance but excludes the internal artifact filename.\n\nDeleting an experiment with registered model versions is restricted by its\ndatabase relationship. Model lifecycle changes should preserve the record of\nwhich fitted artifact produced a result.\n\nAI suggestions\n--------------\n\n``POST /api/ai-suggestions/`` expects ``goal`` and an optional ``version_id``.\nThe request needs an ``X-MLFlowPro-Access-Code`` header containing the private\nteam code. The server also needs its OpenAI key and team-code environment\nsettings. Do not put an OpenAI key in browser JavaScript or the team-code box.\n\nThe response contains a draft suggestion, the provider model identifier, and a\nreview notice. The request context excludes held-out test scores, review text,\nand artifact paths. Suggestions do not execute automatically.\n\nHTTP 403 means the team code did not match, 429 means the application\'s local\nrequest throttle was reached, 503 means required configuration is absent, and\n502 means provider generation failed or produced unusable output. An OpenAI\nquota error was observed during setup; a successful funded provider request is\nstill required before presenting live generation as verified.\n\nWebSocket notes\n---------------\n\nConnect to ``/ws/experiment-notes/`` using ``ws://`` locally or ``wss://`` over\nHTTPS. The first JSON message must authenticate with ``type`` set to\n``authenticate`` and an ``access_code``. A valid connection receives a ``ready``\nmessage with the current document.\n\nA save message uses ``type: save``, a string ``body`` of at most 4,000 characters,\nand the document\'s integer ``revision``. An optional ``request_id`` lets the\nbrowser identify its save acknowledgement. Successful saves are broadcast as\ndocument updates; stale revisions receive ``conflict`` and the latest document.\nThe client can request the current document using ``type: load``.\n\nGitHub login routes\n-------------------\n\n* ``POST /accounts/github/login/`` starts the CSRF-protected OAuth flow.\n* ``GET /accounts/github/login/callback/`` validates the returned state and code.\n* ``POST /team/logout/`` ends the session and requires a CSRF token.\n\nThe GitHub app client secret is exchanged server-side and is never embedded in\nthe dashboard. The access list applies to new and returning social sign-ins.\n', 'docs/source/architecture.rst': 'Architecture and concepts\n=========================\n\nWhat the application does\n-------------------------\n\nAn engineer types a review and selects a saved model version. The browser sends\nthe text and optional version ID to Django. The server loads the corresponding\nscikit-learn pipeline, calculates a prediction, and returns JSON. The browser\ndisplays the label and model probability without reloading the page.\n\nTraining is a separate operation. A training script prepares the data, fits a\npipeline, evaluates it, and stores the settings, results, provenance, and model\nsnapshot. The prediction endpoint uses a fitted pipeline; it does not retrain a\nmodel for every review.\n\nComponent responsibilities\n--------------------------\n\n.. list-table::\n   :header-rows: 1\n   :widths: 30 70\n\n   * - Component\n     - Responsibility\n   * - ``backend/index.html``\n     - Dashboard forms, prediction requests, jQuery version selection, and D3 charts.\n   * - Django and Django REST Framework\n     - HTTP routes, validation, database access, and JSON responses.\n   * - scikit-learn pipelines\n     - TF-IDF feature extraction and sentiment classification.\n   * - PostgreSQL or local SQLite\n     - Experiment, configuration, result, version, and shared-note records.\n   * - Optuna TPE search\n     - Select classifier hyperparameters using training-only cross-validation.\n   * - Local Celery worker\n     - Run tuning outside the web request in another terminal.\n   * - Channels and Daphne\n     - ASGI HTTP serving and WebSocket note updates.\n   * - django-allauth and GitHub\n     - OAuth2 identity verification and team-restricted Django sessions.\n   * - OpenAI integration\n     - Suggest experiment settings and draft Python snippets when configured and funded.\n\nDatabase records and model files\n--------------------------------\n\nThe word "model" has two meanings here. A **Django model** describes a database\nrecord. A **machine learning model** is the fitted classifier inside a saved\npipeline.\n\n.. list-table::\n   :header-rows: 1\n\n   * - Django model\n     - Stored information\n   * - ``Experiment``\n     - Run name, dataset, description, and creation time.\n   * - ``ModelSettings``\n     - Algorithm, TF-IDF feature settings, and hyperparameter JSON for a run.\n   * - ``ExperimentResult``\n     - Measured test accuracy, macro F1, and final training duration.\n   * - ``ModelVersion``\n     - UUID, parameters, metrics, provenance, and the snapshot filename.\n   * - ``CollaborationNote``\n     - Shared planning text, revision number, and last-update time.\n\n``ModelSettings`` fulfills the assignment\'s hyperparameter-settings concept.\nVersioned pipelines live in ``models/versions/``. Their metadata lives in the\ndatabase; the pipeline bytes do not. Selected bundles in ``published_models/``\nallow deployment to restore both the model file and its associated metadata.\n\nReal-time collaboration\n-----------------------\n\nTwo browser tabs connect to ``/ws/experiment-notes/`` and authenticate using the\nteam code in the first message. A successful save updates the database and\nbroadcasts the new note to connected clients. Each save includes the revision\nthe editor started from. If another editor saved first, the server rejects the\nstale write and returns the current document instead of replacing it.\n\nThis is collaboration on saved experiment-planning notes. It is not simultaneous\nediting of training parameters or character-by-character text merging. The\nin-memory channel layer supports the demo\'s single server process; multiple\nprocesses or instances require a shared channel layer such as Redis.\n\nAuthentication and suggestions\n------------------------------\n\nGitHub OAuth verifies identity, then the social-account adapter checks the\nGitHub username against the configured team list. Approved users receive a\nDjango session. Authenticated experiment APIs require that session or another\nsupported authentication method. Browser prediction requests include the CSRF\ntoken so they keep working after sign-in.\n\nThe public prediction demo remains available without an account. Shared notes\nand AI suggestions additionally use their existing private team-code gate.\nThe LLM returns a draft suggestion; the server does not execute generated code\nor automatically accept proposed hyperparameters.\n', 'docs/source/conf.py': '"""Build the project handbook without importing Django or loading secrets."""\n\nproject = "MLFlowPro — HardyBoys"\nauthor = "Elige Diallo, Elijah Sow, Kasaan Dornelus"\ncopyright = "2026, HardyBoys"\nrelease = "Class project"\nextensions = []\nroot_doc = "index"\nexclude_patterns = []\nhtml_theme = "alabaster"\nhtml_title = "MLFlowPro project handbook"\nhtml_theme_options = {"fixed_sidebar": True, "page_width": "1100px"}\nhtml_show_sourcelink = False\nhtml_show_sphinx = False\nhtml_static_path = []\nsmartquotes = False\n', 'docs/source/deployment.rst': "Deployment, testing, and project scope\n======================================\n\nRender configuration\n--------------------\n\nThe public web demo runs at https://hardyboys-ml-project.onrender.com/.\nIts service should deploy the branch that contains the team's current code.\nDuring development that branch is ``feature/django-review-prediction``.\nCommands below assume the service root is the repository root.\n\nThe build script must install backend dependencies, collect static files, apply\nmigrations, load recorded demo results, register the original model versions,\nand restore selected published bundles. Keep those existing initialization\nsteps when changing the start command.\n\nThe ASGI start command is:\n\n.. code-block:: text\n\n   python run_asgi.py\n\nThis starts Daphne bound to Render's supplied port and serves Django HTTP\nrequests plus the notes WebSocket. Gunicorn WSGI alone cannot serve the\nimplemented WebSocket route.\n\nEnvironment variables\n---------------------\n\n.. list-table::\n   :header-rows: 1\n\n   * - Variable\n     - Purpose\n   * - ``DJANGO_SECRET_KEY``\n     - Django signing secret, generated for the deployment.\n   * - ``DJANGO_DEBUG``\n     - ``False`` for the deployed service.\n   * - ``DATABASE_URL``\n     - Hosted PostgreSQL connection URL.\n   * - ``GITHUB_CLIENT_ID`` and ``GITHUB_CLIENT_SECRET``\n     - GitHub OAuth application's credentials.\n   * - ``GITHUB_ALLOWED_USERS``\n     - Comma-separated approved GitHub usernames.\n   * - ``MLFLOWPRO_AI_ACCESS_CODE``\n     - Private team code for notes and AI suggestion requests.\n   * - ``OPENAI_API_KEY``\n     - Server-side provider key for the optional suggestion feature.\n   * - ``OPENAI_MODEL``\n     - Configured suggestion model; the integration default is ``gpt-5.4-mini``.\n\nRender supplies ``RENDER_EXTERNAL_HOSTNAME`` and ``PORT`` to its service. The\nproject uses the hostname in allowed-host and trusted-origin configuration.\nKeep credential values out of source, screenshots, and the generated handbook.\n\nGitHub OAuth setup\n------------------\n\nCreate an OAuth application under GitHub's developer settings. Register both\nof these exact callback URLs, including the trailing slash:\n\n.. code-block:: text\n\n   https://hardyboys-ml-project.onrender.com/accounts/github/login/callback/\n   http://127.0.0.1:8000/accounts/github/login/callback/\n\nEnter its Client ID and Client Secret in the local environment and in Render.\nThe default approved usernames are ``Elitelige7,elsow1,KHD-wq``. Add the\ninstructor's exact username if they need team login. GitHub repository\ncollaborator access is a separate course requirement.\n\nThe implementation requests no additional repository or private-email scope,\nuses OAuth state and PKCE, and does not retain provider tokens. Signed-in users\nreceive Django sessions. Removing a username blocks its next social login;\nit does not invalidate an existing session automatically. This is a team\nauthentication demo, not a complete enterprise identity-management system.\n\nChecks and continuous integration\n---------------------------------\n\nInstall test dependencies and run the project checks:\n\n.. code-block:: powershell\n\n   python -m pip install -r requirements-dev.txt\n   python backend/manage.py check\n   python backend/manage.py makemigrations --check --dry-run\n   python -m pytest -q\n\nTests cover experiment APIs, model-version predictions, invalid inputs, model\npublication, AI request validation with a mocked provider, WebSocket note\nupdates and conflicts, and OAuth callbacks with mocked GitHub HTTP responses.\nProvider mocks do not prove real credentials or paid API access work.\n\nThe backend GitHub Actions workflow runs the configured application checks.\nThe documentation workflow builds these pages with warnings treated as errors.\nCheck the actual Actions run after each push instead of assuming a committed\nworkflow has passed. The container setup includes a Dockerfile, initialization\nscript, and HTTP smoke-check script; confirm the container workflow run before\nclaiming a successful Docker build.\n\nFor a presentation, test the live site in a fresh browser session: sign in,\nsubmit positive and negative reviews, switch a model version, load metrics,\nand sign out. Use two tabs to demonstrate shared-note saves. Confirm real LLM\ngeneration separately if the provider account has usable credit.\n\nImplemented scope and remaining limitations\n-------------------------------------------\n\n* The dashboard supports saved-model inference, a version selector, metrics,\n  and D3 charts.\n* The tracked trainer records actual experiments and supports TPE tuning.\n* Celery tuning has run locally with a filesystem broker; no hosted training\n  worker is established by the web deployment alone.\n* Shared notes use persistent records and single-process WebSocket broadcasts.\n  Multi-instance collaboration needs a shared channel layer.\n* GitHub OAuth code and tests are implemented; real credentials and callbacks\n  must be verified in each environment.\n* OpenAI suggestion code is implemented, but a quota error blocked actual\n  generation during setup. Provider funding and a successful request remain\n  necessary to demonstrate that feature live.\n* Render hosts the web demo. A deployed Kubernetes cluster is not part of the\n  implementation described here.\n\nFinal submission review\n-----------------------\n\nThe README should match the implemented scope and measured results, credit\neach member's actual work, embed a committed ``demo.gif``, and link to the live\napp. Refresh the walkthrough if it needs to show the new features. Confirm all\nthree members have contributed genuine code commits and the instructor has\nbeen added as a repository collaborator.\n\nUseful references\n-----------------\n\n* `Sphinx quickstart <https://www.sphinx-doc.org/en/master/usage/quickstart.html>`_\n* `GitHub OAuth app registration <https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/creating-an-oauth-app>`_\n* `django-allauth configuration <https://docs.allauth.org/en/latest/installation/quickstart.html>`_\n* `Render deployment troubleshooting <https://render.com/docs/troubleshooting-deploys>`_\n", 'docs/source/evaluation.rst': 'Models, evaluation, and results\n===============================\n\nLearning task\n-------------\n\nInput is a written movie review; the target is its positive or negative\nsentiment label. This is binary text classification, not prediction of an IMDb\nrating or a movie\'s box-office performance. Mixed or neutral opinions must\nstill receive one of the two supported labels.\n\nTF-IDF turns review text into numeric features. Individual words and adjacent\nword pairs can become features, up to a 50,000-feature vocabulary. A word pair\ncan retain a phrase such as "not good" that a single-word representation might\nhandle less clearly. The vectorizer learns vocabulary and IDF from training\ndata only.\n\nNaive Bayes and Logistic Regression\n-----------------------------------\n\nMultinomial Naive Bayes estimates which class is more likely from the observed\ntext features, using a conditional-independence assumption. Smoothing\n``alpha`` prevents a feature unseen in one class from producing a zero\nlikelihood. It is a useful fast baseline for sparse text features.\n\nLogistic Regression learns a weight for each feature and converts their\ncombined score into a class probability. Despite its name, the implementation\nhere is a classifier. Its ``C`` hyperparameter controls the strength of\nregularization. Both classifiers see the same TF-IDF representation and split.\n\nNaive Bayes is the classifier being compared; Bayesian optimization is the\nseparate process that searches hyperparameters. TPE tuning does not turn\nLogistic Regression into a Naive Bayes model.\n\nData split and measurement\n--------------------------\n\nThe CSV contains 50,000 labeled reviews before cleaning. The October 19 tuned\nrun retained 49,582 reviews after removing missing rows and duplicate review\ntext. Its split contained 39,665 training reviews and 9,917 test reviews, using\nstratification and random seed 42.\n\nThe tuning objective used three-fold cross-validation within training data.\nHeld-out test labels were excluded from hyperparameter selection. Once the\nfinal test result is reported, repeatedly choosing future settings by that\nsame test score can bias the comparison. Further development should use\ntraining-only validation and preserve a genuinely unseen final evaluation set.\n\nReported results\n----------------\n\nThe baseline rows are the team\'s original reported evaluations. The tuned row\nis the measured October 19 Celery run, which searched six Logistic Regression\nsettings. Values are rounded for display; consult the version\'s stored metrics\nfor full precision.\n\n.. list-table:: Held-out test metrics\n   :header-rows: 1\n\n   * - Model\n     - Accuracy\n     - Macro F1\n   * - Multinomial Naive Bayes baseline\n     - 88.34%\n     - 88.34%\n   * - Logistic Regression baseline\n     - 90.53%\n     - 90.53%\n   * - TPE-tuned Logistic Regression\n     - 91.06%\n     - 91.05%\n\nThe selected ``C`` was 8.102356207766633. Its training-only CV macro F1 was\n0.907489478465694. The final held-out accuracy was 0.9105576283150146 and macro\nF1 was 0.9105466225183032. The version ID was\n``1b1e98fc-5fca-4d0c-98c8-52e459f772ce``. Numeric experiment IDs can differ\nbetween the local database and the restored deployment.\n\nThe tuned run\'s training accuracy was 98.86% and training macro F1 was 98.86%.\nThe gap from its test scores suggests overfitting; a high training score alone\ndoes not establish generalization. Baseline training-set scores were not\nrecorded in the original training output and should not be invented.\n\n.. list-table:: Tuned run confusion matrix\n   :header-rows: 1\n\n   * - Actual label\n     - Predicted negative\n     - Predicted positive\n   * - Negative\n     - 4,460\n     - 480\n   * - Positive\n     - 407\n     - 4,570\n\nAccuracy measures the proportion of correct predictions. Macro F1 calculates\nF1 separately for each class and averages the two equally. A prediction\'s\ndisplayed confidence is a model-estimated probability for that one review;\nit is not measured test accuracy or a guarantee of correctness.\n\nLimits of the conclusions\n-------------------------\n\nThese results concern this dataset, preprocessing, and split. Sarcasm, very\nshort reviews, mixed opinions, and text unlike the training data can fail.\nProbabilities have not been separately calibrated. The comparison does not\nestablish statistical significance or performance on an external dataset.\n\nThe displayed baseline-to-tuned accuracy change is about 0.53 percentage\npoints. Deployment-time reductions and reproducibility percentage gains were\nnot measured. Resume statements and presentation slides should use the actual\nrecorded scores and describe implemented features precisely.\n', 'docs/source/experiments.rst': 'Training, tuning, and versioning\n================================\n\nRun a tracked baseline\n----------------------\n\nWith the dataset in place, migrations applied, and the environment activated:\n\n.. code-block:: powershell\n\n   python train_and_track_tuning.py --model both\n\nThe script drops missing values and duplicate review text, makes a stratified\n80/20 split with seed 42, and fits TF-IDF only on the training portion. It saves\nboth an experiment record and a new UUID-named model snapshot. The original\n``train_models.py`` script is the simpler baseline trainer; it replaces the\ntwo original files in ``models/`` instead of logging versioned experiments.\n\nAn experiment captures what was tried, and a model version identifies the\nspecific fitted pipeline produced by that run. Refresh the dashboard to load\nnew versions and click **Load Experiment Metrics** to compare their results.\n\nTune Logistic Regression\n------------------------\n\n.. code-block:: powershell\n\n   python train_and_track_tuning.py --model logistic_regression --optimize --trials 6\n\nOptuna\'s Tree-structured Parzen Estimator (TPE) searches for ``C``. The objective\nis mean macro F1 from three stratified folds within the training set. TF-IDF\nstays inside the pipeline for each fold, so validation-fold text is excluded\nfrom vocabulary and IDF fitting. After selecting settings, the script fits on\nthe full training portion and evaluates on the held-out test portion.\n\nLarger ``C`` means weaker regularization in Logistic Regression. It allows a\ncloser fit to training data and can increase overfitting. The search tests this\ntradeoff using cross-validation rather than assuming a larger value is better.\nFor Naive Bayes, the corresponding tuning command searches its smoothing\nparameter ``alpha``:\n\n.. code-block:: powershell\n\n   python train_and_track_tuning.py --model naive_bayes --optimize --trials 6\n\nThe script records the trials, selected settings, training-only CV score,\ndataset hash, split hashes, package versions, final metrics, and model-file\nhash. Matching inputs, split settings, and dependency versions supports\nreproduction; it does not establish a measured percentage improvement in\n"reproducibility."\n\nRun tuning in the background\n----------------------------\n\nOpen a separate PowerShell terminal and leave the worker running:\n\n.. code-block:: powershell\n\n   cd C:\\Users\\elige\\hardyboys-ml-project\n   .\\.venv\\Scripts\\Activate.ps1\n   python background_jobs.py worker\n\nIn another activated terminal at the same project root:\n\n.. code-block:: powershell\n\n   python background_jobs.py enqueue --model logistic_regression --trials 6\n\nThe command returns a job ID immediately. Copy it into a status command, for\nexample replacing ``YOUR_JOB_ID`` here with the returned UUID:\n\n.. code-block:: powershell\n\n   python background_jobs.py status YOUR_JOB_ID\n\nThe local broker uses the filesystem and stores task results in SQLite under\n``local_jobs/``. Worker and client processes must share that directory. This is\na demonstrated local background job, not a hosted distributed worker. A Render\nworker on another machine would need a shared broker, database configuration,\nand model-artifact storage.\n\nPublish a selected version\n--------------------------\n\nCopy the desired UUID from the registry or training output:\n\n.. code-block:: powershell\n\n   python publish_model.py export YOUR_VERSION_ID\n\nThis creates ``published_models/<version-id>/model.joblib`` and\n``manifest.json``. The manifest retains settings, provenance, measured metrics,\nand a checksum. Commit the selected bundle and deploy it. The deployment build\nruns:\n\n.. code-block:: powershell\n\n   python publish_model.py restore\n\nRestore verifies the checksum and recreates the model snapshot and records.\nRuntime snapshots under ``models/versions/`` are ignored by Git; selected\npublished bundles are intentionally committed. Publish only artifacts your\nteam generated or otherwise trusts, because joblib loading deserializes Python\nobjects.\n', 'docs/source/index.rst': "MLFlowPro project handbook\n==========================\n\nMLFlowPro helps a machine learning engineer train, compare, save, and use\nmovie-review sentiment models. The demo classifies review text as positive or\nnegative using TF-IDF with Naive Bayes or Logistic Regression. Django stores\nexperiment settings, measured results, and model-version metadata.\n\nThis handbook describes the HardyBoys implementation. It distinguishes the\ndeployed web demo, the local training worker, and features that need additional\nconfiguration. The original assignment describes a broader product vision.\n\nLive application: https://hardyboys-ml-project.onrender.com/\n\nRepository: https://github.com/Elitelige7/hardyboys-ml-project\n\n.. toctree::\n   :maxdepth: 2\n\n   setup\n   architecture\n   experiments\n   api\n   evaluation\n   deployment\n\nStart here\n----------\n\n* To run the demo locally, follow :doc:`setup`.\n* To understand what each component does, read :doc:`architecture`.\n* To train or tune a model, follow :doc:`experiments`.\n* To explain the measured scores, use :doc:`evaluation`.\n\nTeam\n----\n\nElige Diallo, Elijah Sow, and Kasaan Dornelus. Individual responsibilities and\ncontributions should be recorded in the repository README and supported by each\nmember's own commits.\n", 'docs/source/setup.rst': 'Installation and local setup\n============================\n\nPrerequisites\n-------------\n\nUse Python 3.11, Git, and a terminal. These instructions use Windows PowerShell.\nRun project commands from the repository root, which contains the ``backend``\ndirectory. The project\'s Python dependencies are pinned in\n``backend/requirements.txt``; documentation dependencies are separate.\n\nCreate your environment\n-----------------------\n\nFor a new checkout:\n\n.. code-block:: powershell\n\n   git clone https://github.com/Elitelige7/hardyboys-ml-project.git\n   cd hardyboys-ml-project\n   git switch feature/django-review-prediction\n   python -m venv .venv\n   .\\.venv\\Scripts\\Activate.ps1\n   python -m pip install -r backend/requirements.txt\n\nFor an existing checkout, activate its existing environment instead of creating\nanother one. The ``(.venv)`` prefix confirms activation. Use ``python -m pip``\nso packages install into the same interpreter that runs the app.\n\nConfiguration\n-------------\n\nCreate ``backend/.env`` in your editor. A minimal local file contains:\n\n.. code-block:: text\n\n   DJANGO_SECRET_KEY=replace_with_a_generated_secret\n   DJANGO_DEBUG=True\n\nGenerate the secret value in your activated environment:\n\n.. code-block:: powershell\n\n   python -c "import secrets; print(secrets.token_urlsafe(50))"\n\nThe local database defaults to SQLite when ``DATABASE_URL`` is absent. A\nPostgreSQL URL selects the hosted database configuration. Store credentials in\nthe local environment file or Render environment settings, and exclude them\nfrom Git.\n\nPrepare the database and model registry\n---------------------------------------\n\n.. code-block:: powershell\n\n   python backend/manage.py migrate\n   python backend/manage.py loaddata backend/demo_results.json\n   python register_model_versions.py\n   python publish_model.py restore\n   python backend/manage.py runserver\n\nOpen http://127.0.0.1:8000/ and leave the server terminal running. The restore\ncommand imports any committed published-model bundles; it reports that none\nwere found if there are no bundles in that checkout. The app uses included\nsaved models, so a dataset download is unnecessary for normal predictions.\n\nTry a positive review and a negative review, select a saved version, and click\n**Load Experiment Metrics**. The same result response fills the table and the\nD3 comparison chart.\n\nDataset for training\n--------------------\n\nDownload the CSV from the `IMDb 50K dataset page\n<https://www.kaggle.com/datasets/lakshmi25npathi/imdb-dataset-of-50k-movie-reviews>`_.\nExtract it to ``data/IMDB Dataset.csv``. The training scripts expect ``review``\nand ``sentiment`` columns, with ``positive`` and ``negative`` labels. Do not add\nthe dataset to Git.\n\nOptional features\n-----------------\n\n* GitHub sign-in needs ``GITHUB_CLIENT_ID``, ``GITHUB_CLIENT_SECRET``, and\n  ``GITHUB_ALLOWED_USERS``. See :doc:`deployment`.\n* AI suggestions need ``OPENAI_API_KEY`` and the private\n  ``MLFLOWPRO_AI_ACCESS_CODE``. A provider quota error means real generation has\n  not succeeded; the rest of the dashboard can still operate.\n* Shared notes use ``MLFLOWPRO_AI_ACCESS_CODE`` too. They do not make an LLM\n  request and do not require OpenAI credit.\n\nBuild this handbook\n-------------------\n\n.. code-block:: powershell\n\n   python -m pip install -r requirements-docs.txt\n   python -m sphinx -n -W --keep-going -b html docs/source docs/build/html\n   Start-Process .\\docs\\build\\html\\index.html\n\nThe HTML build is local documentation; it is separate from the Django\ndashboard. The documentation workflow on GitHub runs the same build check.\n', '.github/workflows/documentation.yml': 'name: Documentation\n\n"on":\n  push:\n    paths:\n      - "docs/**"\n      - "requirements-docs.txt"\n      - "add_project_docs.py"\n      - ".github/workflows/documentation.yml"\n  pull_request:\n    paths:\n      - "docs/**"\n      - "requirements-docs.txt"\n      - "add_project_docs.py"\n      - ".github/workflows/documentation.yml"\n  workflow_dispatch:\n\npermissions:\n  contents: read\n\njobs:\n  build:\n    runs-on: ubuntu-latest\n    timeout-minutes: 5\n    steps:\n      - name: Check out repository\n        uses: actions/checkout@v6\n        with:\n          persist-credentials: false\n      - name: Set up Python\n        uses: actions/setup-python@v6\n        with:\n          python-version: "3.11"\n          cache: pip\n          cache-dependency-path: requirements-docs.txt\n      - name: Install documentation dependencies\n        run: python -m pip install -r requirements-docs.txt\n      - name: Build project handbook\n        run: python -m sphinx -n -W --keep-going -b html docs/source docs/build/html\n', 'requirements-docs.txt': "# Sphinx 8.2.3 supports the project's Python 3.11 environment.\nSphinx==8.2.3\n"}

README_LINK = '\n\n<!-- MLFlowPro: Sphinx handbook -->\n## Project handbook\n\nSee [the documentation guide](docs/README.md) for setup, architecture, training\nand tuning, API usage, evaluation, deployment, and current limitations.\n\nBuild the searchable HTML handbook from the repository root:\n\n```powershell\npython -m pip install -r requirements-docs.txt\npython -m sphinx -n -W --keep-going -b html docs/source docs/build/html\n```\n'


def main():
    root = Path(__file__).resolve().parent
    required = ["README.md", "backend/manage.py", "backend/index.html"]
    missing = [name for name in required if not (root / name).is_file()]
    if missing:
        raise SystemExit("Save this helper in the project root first. Missing: " + ", ".join(missing))
    contents = dict(FILES)

    readme = (root / "README.md").read_text(encoding="utf-8-sig")
    if "<!-- MLFlowPro: Sphinx handbook -->" not in readme:
        readme = readme.rstrip() + README_LINK
    contents["README.md"] = readme

    ignore_path = root / ".gitignore"
    ignore = ignore_path.read_text(encoding="utf-8-sig") if ignore_path.is_file() else ""
    missing_patterns = [pattern for pattern in ["docs/build/", "local_jobs/"]
                        if pattern not in {line.strip().lstrip("/") for line in ignore.splitlines()}]
    if missing_patterns:
        ignore = ignore.rstrip() + "\n\n# Generated documentation and local runtime files\n"
        ignore += "\n".join(missing_patterns) + "\n"
    contents[".gitignore"] = ignore

    for relative, content in contents.items():
        if relative.endswith(".py"):
            ast.parse(content, filename=relative)
    backup = root / "local_jobs" / "backups" / ("documentation-" + datetime.now().strftime("%Y%m%d-%H%M%S-%f"))
    for relative, content in contents.items():
        target = root / relative
        if target.is_file() and target.read_text(encoding="utf-8") != content:
            saved = backup / relative
            saved.parent.mkdir(parents=True, exist_ok=True)
            saved.write_bytes(target.read_bytes())
    for relative, content in contents.items():
        target = root / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        print("Ready:", relative)
    if backup.exists():
        print("Previous files backed up at:", backup)
    print("Next: python -m pip install -r requirements-docs.txt")
    print("Build: python -m sphinx -n -W --keep-going -b html docs/source docs/build/html")
    print("Open in PowerShell: Start-Process .\\docs\\build\\html\\index.html")
    print("A documentation build check is included in GitHub Actions.")


if __name__ == "__main__":
    main()
